\u006c\u006f\u0054\u007e\u005f\u0027\u0062\u0071\u0059\u0037\u0062\u0038\u0049\u006c\u004d\u0040\u0052\u0041\u0036\u0038\u0064\u004c\u0059\u0040\u004a\u0022\u0042\u0030\u0027\u005c\u006b\u005b\u004e\u0021\u0048\u0042\u0063\u0063\u0036\u0030\u0055\u003f\u0044\u0044\u006c\u0021\u0059\u005b\u0026\u0022\u0030\u0020\u0067\u0034\u0054\u0077\u0067\u006b\u007d\u0077\u005f\u0041\u006e\u0046\u004a\u0033\u0056\u004e\u003e\u0069\u0035\u0077\u0038\u0030\u0054\u0064\u004e\u0071\u005a\u0023\u0043\u0040\u0051\u0023\u0079\u0045\u0079\u007a\u0027\u006d\u0050\u002f\u0023\u0070\u0045\u0073\u0039\u003d\u0038\u006a\u002c\u0022\u0078\u0034\u0074\u004d\u0022\u006a\u006e\u0042\u0075\u0078\u0037\u0068\u0061\u0043\u0023\u0066\u0051\u007c\u005b\u0075\u0046\u0032\u002b\u006b\u0077\u007e\u0079\u0066\u0055\u0073\u0041\u0044\u006e\u004a\u0063\u007a\u0074\u004b\u006a\u007d\u0074\u0022\u0033\u0062\u003b\u0077\u0042\u0049\u003e\u0043\u003d\u0050\u0049\u0023\u0065\u004f\u0042\u005b\u0068\u0048\u0065\u0066\u0070\u007a\u0048\u006c\u0028\u0023\u0054\u0061\u0024\u005f\u0035\u006b\u0059\u0040\u003d\u007b\u005e\u005f\u002b\u005f\u0020\u0045\u003e\u002e\u0024\u0059\u004e\u005d\u002a\u003f\u005b\u0067\u0033\u0060\u004c\u0056\u0020\u004d\u006c\u0075\u0069\u002f\u006a\u0042\u005a\u0054\u004c\u0053\u0054\u002f\u0023\u0073\u004f\u0077\u002e\u006d\u0079\u0079\u0035\u0061\u006c\u0052\u005d\u005d\u0061\u0039\u0063\u007a\u0052\u0074\u0022\u006b\u0057\u0025\u0077\u0028\u0029\u0065\u003c\u0048\u0034\u0027\u006f\u004a\u004d\u0079\u0042\u0033\u0073\u0032\u006d\u0033\u0055\u0048\u0038\u0061\u0034\u0055\u0060\u0067\u0034\u0045\u005e\u0030\u0037\u003c\u0054\u0027\u005e\u0075\u0047\u0040\u007b\u0057\u005d\u007e\u0070\u0046\u0065\u0027\u0053\u0072\u0050\u0039\u0047\u005b\u0026\u0039\u002d\u0030\u0074\u0078\u004d\u0032\u0066\u0052\u006e\u0022\u0032\u0024\u0031\u0061\u006e\u0048\u002e\u0059\u0020\u0078\u0036\u0032\u007d\u0072\u0075\u0073\u0066\u0065\u0035\u007a\u0031\u0048\u007b\u0021\u0069\u004b\u0070\u0043\u0029\u007b\u0063\u006c\u004f\u0042\u005b\u003f\u0070\u006d\u0050\u0055\u0056\u005d\u004f\u0031\u0028\u0030\u0034\u0050\u0050\u007b\u0068\u0078\u0062\u002a\u004b\u002a\u006a\u006d\u007e\u0064\u0035\u007a\u0071\u0057\u007b\u002f\u005d\u0041\u005f\u0049\u004c\u0076\u0042\u006d\u0042\u0025\u0025\u002e\u0051\u0076\u007c\u0048\u0079\u005e\u0075\u003a\u002a\u0077\u0026\u0049\u0021\u0038\u002e\u0022\u0053\u0040\u0054\u002f\u0032\u0059\u0051\u0026\u006b\u0059\u0044\u0067\u0042\u0039\u0042\u005d\u0068\u006a\u0036\u0035\u0063\u003a\u0074\u004f\u003a\u0042\u0056\u0036\u0048\u0029\u0064\u005b\u0033\u0032\u006e\u0026\u0043\u007a\u007b\u004c\u007e\u0022\u0061\u005d\u0051\u0043\u005d\u0054\u004f\u0021\u0071\u0033\u002b\u0038\u0067\u0048\u0067\u0058\u0057\u006b\u0069\u0075\u002e\u0078\u006d\u0050\u007c\u0050\u0057\u0037\u005b\u0021\u0020\u003d\u0072\u002d\u0079\u0065\u0043\u005f\u005f\u0077\u003d\u0042\u0071\u0039\u0039\u0051\u0024\u0066\u0045\u0051\u0028\u0066\u007e\u0045\u0068\u0052\u0026\u0068\u0031\u003b\u002e\u0035\u004d\u004f\u004e\u002d\u0053\u0042\u0033\u0046\u0036\u0073\u0041\u003c\u0058\u0023\u0030\u0041\u0059\u0022\u007a\u0059\u006f\u0024\u003d\u0024\u0024\u0043\u0061\u003d\u0037\u0024\u0041\u005d\u0069\u0021\u003e\u0050\u005b\u002f\u004c\u007b\u0021\u0067\u004b\u0062\u006a\u006d\u002e\u0056\u0060\u003d\u005a\u0059\u0028\u0061\u002b\u0051\u005b\u0068\u005d\u0057\u0068\u0065\u0068\u007c\u0028\u0047\u005a\u002e\u0049\u0046\u002f\u006a\u0067\u005a\u004f\u0021\u0063\u004d\u0060\u006a\u0039\u0074\u004a\u0051\u0041\u0067\u0038\u0067\u007c\u006a\u0037\u002d\u0048\u0070\u007b\u003e\u0076\u0052\u006d\u007a\u0037\u0027\u0042\u0050\u003c\u005f\u0065\u005c\u004f\u006f\u0021\u0056\u0037\u005d\u0039\u0027\u003e\u0046\u006d\u007c\u0077\u006f\u0071\u003c\u002e\u0034\u0022\u0036\u0042\u0065\u0020\u0051\u0042\u0053\u003e\u0077\u006b\u007e\u0068\u006f\u006a\u004e\u004f\u0023\u007e\u0036\u0041\u0052\u007a\u0051\u0071\u0063\u002b\u0047\u0022\u007e\u0078\u004e\u005f\u0047\u0034\u006f\u0057\u0040\u0042\u0022\u007a\u002c\u0074\u0077\u0066\u006e\u002a\u003e\u0079\u0047\u006a\u004a\u0040\u0026\u0054\u002b\u0050\u0072\u0059\u0038\u004d\u007d\u0061\u0028\u0046\u0065\u0076\u0074\u0021\u0028\u0040\u002d\u002c\u0070\u005a\u0058\u002c\u0072\u003b\u0063\u0070\u007e\u0060\u0064\u0059\u0038\u0058\u0075\u0046\u006b\u0052\u0059\u0075\u006b\u0021\u0064\u0060\u0063\u007c\u005a\u002e\u0027\u002f\u003e\u006c\u0057\u0028\u0049\u0076\u002c\u006f\u0066\u002e\u0059\u004c\u007a\u006e\u0044\u0055\u0050\u0045\u0065\u0047\u007e\u005c\u0034\u0038\u0033\u004b\u002c\u005a\u0026\u0071\u0066\u004a\u0075\u0060\u002c\u0067\u0055\u006c\u0069\u0043\u0073\u0041\u0045\u0047\u0077\u0029\u002b\u0020\u0031\u0050\u0023\u0050\u0077\u005b\u002a\u0053\u004d\u0046\u0025\u0040\u004c\u0076\u006a\u0032\u0039\u007a\u0031\u0056\u0028\u0058\u0023\u0071\u007c\u0063\u0049\u0051\u0037\u0055\u0029\u0059\u003e\u0034\u0051\u0072\u002f\u0067\u0049\u003a\u0057\u0064\u0028\u0044\u0066\u0061\u005d\u006d\u0050\u002a\u007a\u0023\u003e\u0058\u0066\u0055\u005e\u005a\u0034\u004a\u002a\u004d\u005f\u002e\u0031\u002f\u0051\u0065\u0050\u0030\u006a\u0060\u0030\u004b\u0032\u0040\u007b\u005c\u003d\u006b\u0025\u007e\u0049\u002f\u0032\u0026\u007d\u0038\u0069\u005f\u0025\u0050\u006e\u0067\u004a\u004a\u007e\u0071\u004f\u004d\u003a\u0056\u0050\u0066\u0077\u0058\u0068\u0033\u004c\u0055\u005e\u0077\u0067\u0078\u0078\u0029\u0042\u005e\u002b\u0054\u002e\u005a\u0049\u0054\u002f\u007e\u0067\u007d\u005b\u0077\u006d\u0049\u0067\u0062\u004b\u0046\u0032\u0066\u0062\u0078\u0041\u0062\u003f\u0070\u004d\u0044\u0056\u007e\u0026\u0070\u007d\u007d\u007d\u0044\u0020\u0055\u0077\u0048\u0046\u002f\u0065\u0057\u0024\u0061\u0074\u004a\u0070\u006a\u003f\u0056\u003b\u005c\u003d\u0020\u0058\u0032\u0046\u0054\u005d\u007e\u0032\u004b\u0040\u0029\u006c\u0068\u0074\u0048\u0066\u003e\u002c\u003f\u0033\u0074\u004c\u0052\u0024\u002c\u0031\u0054\u0061\u006c\u0075\u0035\u002e\u0067\u0046\u0046\u0052\u0050\u0061\u0050\u0030\u0043\u0029\u004f\u0057\u002a\u007b\u002b\u004f\u0065\u0046\u0071\u0055\u0073\u0022\u0040\u002b\u0060\u005a\u0072\u003a\u0028\u007e\u0036\u0040\u002f\u0035\u0070\u007b\u0034\u007b\u0070\u0074\u0038\u0064\u003b\u002e\u0021\u0075\u003e\u0079\u005e\u005f\u0078\u0070\u002b\u0062\u0027\u005d\u0072\u0065\u007d\u0079\u005a\u0021\u006d\u006e\u005d\u0021\u0074\u0079\u007d\u004b\u004c\u005c\u0068\u0062\u007a\u0026\u0076\u0044\u006a\u002a\u007d\u0021\u004f\u003b\u003b\u0067\u0062\u0067\u0054\u006c\u007a\u0026\u007b\u004b\u0022\u0051\u007d\u0040\u003f\u0030\u0035\u0066\u0074\u0072\u003c\u0038\u0030\u0070\u0053\u005d\u0034\u0020\u0029\u002e\u0077\u007c\u003e\u006c\u0070\u0077\u0073\u0053\u0041\u0073\u0062\u002f\u0061\u0031\u003b\u0061\u0020\u0068\u0057\u0041\u0073\u002f\u006c\u0029\u004f\u0028\u0039\u0023\u005c\u0076\u0022\u0027\u003a\u004d\u005c\u0056\u003e\u0072\u0025\u0055\u003c\u003d\u006f\u006d\u0066\u0041\u0048\u0034\u0028\u0069\u007d\u0068\u003f\u0035\u0052\u0024\u006b\u0079\u005e\u0031\u0066\u0028\u0054\u0059\u004c\u003a\u0053\u007c\u0073\u0026\u004e\u004c\u003d\u004c\u005b\u0075\u005a\u005b\u005f\u0030\u0022\u0077\u0025\u0055\u004c\u0057\u005e\u005b\u0034\u002b\u0068\u0040\u0027\u0027\u0079\u007d\u0061\u0031\u004a\u0058\u005a\u0054\u007c\u0066\u0058\u0063\u0027\u0025\u003e\u007c\u0029\u0036\u007b\u0023\u0022\u0046\u004b\u0065\u0070\u0030\u0043\u0048\u0078\u0051\u002d\u0052\u0075\u004f\u006a\u004f\u0057\u0036\u004c\u0059\u0038\u003b\u0035\u004a\u002c\u0026\u0079\u0076\u0058\u0051\u0077\u0060\u0028\u0079\u002f\u005f\u0039\u0020\u0022\u0029\u003f\u0064\u0032\u006c\u0054\u0076\u0027\u0035\u0076\u006e\u0043\u0053\u004b\u0028\u0058\u007d\u005b\u0075\u006c\u003d\u0056\u0059\u0020\u0048\u0059\u0032\u0039\u0059\u0020\u004d\u004f\u004b\u0077\u0032\u0053\u0022\u0040\u005f\u002d\u005b\u0036\u0042\u002c\u0058\u0051\u003f\u0071\u0021\u003e\u0034\u004a\u003b\u0053\u005c\u002a\u0042\u005b\u003b\u0059\u0059\u0071\u0053\u005c\u0028\u0067\u0045\u0030\u0067\u004c\u0071\u007a\u0069\u0040\u002f\u0021\u007e\u002c\u004d\u003f\u003c\u0023\u002e\u0069\u005f\u005e\u0071\u0030\u0077\u0045\u002e\u0027\u0037\u006a\u002f\u0067\u0078\u004b\u005b\u006b\u0045\u002e\u003c\u005e\u003b\u005c\u003a\u0068\u0036\u0053\u007a\u0059\u0023\u004b\u0039\u004d\u0050\u0074\u0075\u006f\u0023\u0021\u0052\u007e\u0072\u0024\u0036\u002d\u004b\u005e\u0057\u0071\u0035\u0065\u0024\u002a\u0023\u0078\u0050\u004f\u002c\u0025\u0069\u0025\u0072\u0049\u0055\u004a\u002a\u0040\u002e\u0043\u0026\u0064\u0062\u006f\u0063\u005c\u0072\u0029\u003b\u0021\u006b\u0050\u0042\u0030\u007b\u0070\u005e\u0068\u0024\u0069\u0059\u0040\u0021\u0059\u0024\u005f\u0021\u0023\u0062\u003d\u0026\u003b\u003c\u0030\u0062\u002b\u005b\u004c\u002e\u0079\u003e\u0077\u0024\u003f\u005f\u0065\u003b\u0055\u0055\u006c\u0042\u0075\u0038\u004f\u0072\u0039\u0042\u004e\u0027\u0041\u007c\u0045\u0025\u007e\u0040\u0049\u0031\u003e\u007e\u0066\u0041\u007b\u006e\u0042\u0053\u0061\u0062\u0056\u0057\u0057\u0064\u004a\u0041\u002e\u0067\u004e\u0048\u0021\u006d\u0024\u0048\u0048\u002e\u005e\u007e\u003f\u0058\u0028\u005b\u0039\u002c\u0066\u0061\u0064\u0023\u0027\u0043\u0078\u0047\u006f\u0076\u0036\u0058\u002b\u0073\u0049\u0045\u002f\u007c\u007a\u002a\u0072\u007e\u005d\u0056\u004c\u004f\u0051\u0023\u0021\u0059\u0076\u002b\u0063\u007b\u004b\u0040\u0049\u0069\u003f\u0053\u0030\u005b\u0036\u0073\u003f\u0045\u004c\u0028\u0078\u005d\u0046\u0046\u005c\u004e\u006f\u0038\u0039\u0072\u002c\u0033\u0067\u003b\u0068\u0027\u006c\u007e\u0043\u006c\u002d\u0056\u0020\u0062\u0044\u0042\u0047\u005d\u002f\u003c\u007b\u0043\u004e\u004f\u0066\u0024\u002d\u003a\u0041\u0071\u004a\u0064\u0049\u0053\u0078\u003d\u0061\u0037\u006d\u0043\u005a\u0064\u0036\u0033\u0055\u0033\u004b\u0046\u0077\u0050\u0033\u006f\u0064\u0062\u0048\u004d\u0054\u007a\u0020\u0079\u0034\u0022\u0025\u004a\u0025\u0058\u0039\u002d\u003e\u0030\u003a\u0026\u0040\u003a\u006c\u0064\u007c\u006c\u0029\u0072\u0076\u0065\u0053\u0055\u007b\u0057\u0029\u0054\u0069\u0040\u004f\u0033\u0058\u0030\u0073\u006b\u002b\u0021\u0046\u0056\u0051\u006b\u0060\u0067\u002e\u0072\u0027\u007a\u0031\u003d\u005d\u0072\u007b\u004f\u006c\u004a\u0049\u0061\u0061\u0029\u0070\u007e\u0031\u0078\u0032\u0051\u002c\u0048\u0055\u0063\u0051\u0024\u0069\u0038\u0078\u0063\u0032\u0053\u0061\u0044\u0030\u0036\u007b\u007d\u002c\u0054\u002a\u002a\u0030\u0045\u0060\u0065\u0042\u003d\u007e\u006e\u0061\u0031\u0055\u0069\u0074\u005a\u0026\u006b\u006c\u0044\u0055\u007b\u004a\u007e\u0074\u003d\u004a\u0021\u006c\u004e\u0077\u0026\u0031\u0071\u0077\u0050\u007c\u002b\u0021\u0034\u0078\u0049\u0046\u005c\u002d\u002f\u005b\u006c\u0075\u0060\u0066\u007b\u0066\u0050\u0078\u0070\u0068\u004a\u0032\u0073\u004e\u004a\u004b\u0034\u0047\u0061\u006b\u0028\u0068\u0038\u003d\u0066\u0076\u006b\u003d\u005f\u0061\u004b\u002f\u0035\u005d\u004d\u004e\u007d\u0038\u0037\u0029\u0026\u0045\u0031\u005c\u0041\u003a\u0069\u002c\u0066\u0026\u0077\u0071\u007c\u006a\u0063\u0037\u004e\u0020\u0043\u0075\u003a\u0057\u0041\u0067\u007a\u0059\u004a\u007e\u0051\u002d\u005d\u0030\u0065\u0071\u0072\u006e\u0048\u005f\u0022\u005c\u0030\u0078\u002e\u0033\u0031\u002b\u0047\u0062\u0068\u0065\u005b\u006b\u006d\u0021\u0052\u006d\u0060\u003d\u0023\u0023\u0077\u0037\u005a\u0026\u005f\u0069\u0045\u007c\u0055\u0042\u0040\u006c\u007b\u004c\u0045\u0072\u0030\u0049\u0058\u0058\u0027\u007d\u005b\u0058\u0020\u0056\u003e\u0048\u0074\u005c\u004d\u003b\u004e\u0061\u0063\u0028\u002d\u0023\u0067\u0031\u004a\u0066\u0038\u0021\u003b\u0074\u0052\u003c\u0072\u0075\u0075\u0076\u0066\u0024\u0021\u0032\u0057\u0047\u0044\u007a\u0077\u0034\u0024\u0029\u007e\u004d\u0023\u0076\u002a\u006f\u0048\u002b\u0054\u0025\u002a\u0055\u004a\u006c\u0071\u0075\u006e\u0029\u002c\u0020\u004f\u0071\u0034\u0055\u0031\u0042\u0060\u0063\u0042\u005a\u002b\u0059\u006e\u005f\u0079\u0053\u0061\u007d\u007c\u007e\u0074\u0047\u0038\u0020\u0028\u006d\u005d\u0038\u0039\u0036\u0060\u0048\u0065\u002a\u0023\u006e\u0073\u0052\u0050\u006f\u004c\u007d\u006f\u006f\u0036\u0028\u0057\u0022\u0031\u0066\u0058\u0059\u004b\u006b\u0027\u006b\u003f\u0059\u006f\u002f\u005e\u0066\u0054